function solve(args) {
  const minSub = (a) => {
    let best = Infinity, cur = 0;
    for (const n of a) {
      cur = Math.min(n, cur + n);
      best = Math.min(best, cur);
    }
    return best;
  };
  const oddProd = (n) => {
    let p = 1, found = false;
    for (const c of String(n)) {
      const d = +c;
      if (d % 2 === 1) { p *= d; found = true; }
    }
    return found ? p : 0;
  };
  const mono = (a) => {
    let inc = true, dec = true;
    for (let i = 1; i < a.length; i++) {
      if (a[i] < a[i - 1]) inc = false;
      if (a[i] > a[i - 1]) dec = false;
    }
    return inc || dec;
  };
  const ext = (name, arr) => {
    let best = -Infinity, chosen = arr[0];
    for (const s of arr) {
      let sc = 0;
      for (const c of s) {
        if (c >= 'A' && c <= 'Z') sc++;
        else if (c >= 'a' && c <= 'z') sc--;
      }
      if (sc > best) { best = sc; chosen = s; }
    }
    return name + '.' + chosen;
  };
  const signSum = (a) => {
    if (!a.length) return null;
    let sum = 0, neg = 0, zero = false;
    for (const n of a) {
      sum += Math.abs(n);
      if (n < 0) neg++;
      if (n === 0) zero = true;
    }
    if (zero) return 0;
    return neg % 2 === 1 ? -sum : sum;
  };
  return [
    minSub(args[0][0]),
    oddProd(args[1][0]),
    mono(args[2][0]),
    ext(args[3][0], args[3][1]),
    signSum(args[4][0])
  ];
}

