function solve(args) {
  const pal = ([n]) => {
    let even = 0, odd = 0;
    for (let i = 1; i <= n; i++) {
      const s = String(i);
      if (s === [...s].reverse().join('')) {
        if (i % 2 === 0) even++; else odd++;
      }
    }
    return [even, odd];
  };
  const signSum = ([a]) => {
    if (a.length === 0) return null;
    let sign = 1, sum = 0;
    for (const n of a) {
      if (n === 0) return 0;
      if (n < 0) sign = -sign;
      sum += Math.abs(n);
    }
    return sign * sum;
  };
  const minSub = ([a]) => {
    let best = Infinity, cur = 0;
    for (const n of a) {
      cur = Math.min(n, cur + n);
      best = Math.min(best, cur);
    }
    return best;
  };
  const mono = ([a]) => {
    if (a.length < 2) return true;
    let inc = true, dec = true;
    for (let i = 1; i < a.length; i++) {
      if (a[i] < a[i - 1]) inc = false;
      if (a[i] > a[i - 1]) dec = false;
    }
    return inc || dec;
  };
  const transform = ([a]) => {
    let s = 0;
    for (let i = 0; i < a.length; i++) {
      const n = a[i];
      if (i % 3 === 0) s += n * n;
      else if (i % 4 === 0) s += n * n * n;
      else s += n;
    }
    return s;
  };
  return [pal(args[0]), signSum(args[1]), minSub(args[2]), mono(args[3]), transform(args[4])];
}

