  const isPrime = n => {
    if (n < 2) return false;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) return false;
    return true;
  };
  const A = (() => {
    const n = args[0][0];
    const r = [];
    for (let k = 2; k < n; k++) if (isPrime(k)) r.push(k);
    return r;
  })();
  const B = (() => {
    const a = args[1][0];
    let best = Infinity;
    for (let i = 0; i < a.length; i++) {
      let s = 0;
      for (let j = i; j < a.length; j++) {
        s += a[j];
        if (s < best) best = s;
      }
    }
    return best;
  })();
  const C = (() => {
    const a = args[2][0];
    const n = a.length;
    for (let i = 0; i < n; i++)
      for (let j = i + 1; j < n; j++)
        for (let k = j + 1; k < n; k++)
          if (a[i] + a[j] + a[k] === 0) return true;
    return false;
  })();
  const D = (() => {
    const a = args[3][0];
    let s = 0;
    for (let i = 0; i < a.length; i++) {
      const v = a[i];
      if (i % 3 === 0) s += v * v;
      else if (i % 4 === 0) s += v * v * v;
      else s += v;
    }
    return s;
  })();
  const E = (() => {
    const n = args[4][0];
    let even = 0, odd = 0;
    for (let i = 1; i <= n; i++) {
      const s = String(i);
      if (s === [...s].reverse().join('')) {
        if (i % 2 === 0) even++; else odd++;
      }
    }
    return [even, odd];
  })();
  return [A, B, C, D, E];
}

