function solve(args) {
  const A = (() => {
    const a = args[0][0];
    let inc = true, dec = true;
    for (let i = 1; i < a.length; i++) {
      if (a[i] < a[i - 1]) inc = false;
      if (a[i] > a[i - 1]) dec = false;
    }
    return inc || dec;
  })();
  const B = (() => {
    const a = args[1][0].slice();
    const idx = [];
    for (let i = 0; i < a.length; i += 3) idx.push(i);
    const vals = idx.map(i => a[i]).sort((x, y) => x - y);
    idx.forEach((i, j) => { a[i] = vals[j]; });
    return a;
  })();
  const C = (() => {
    const name = args[2][0], exts = args[2][1];
    let best = 0, bestScore = -Infinity;
    for (let i = 0; i < exts.length; i++) {
      let s = 0;
      for (const ch of exts[i]) {
        if (ch >= 'A' && ch <= 'Z') s++;
        else if (ch >= 'a' && ch <= 'z') s--;
      }
      if (s > bestScore) { bestScore = s; best = i; }
    }
    return name + '.' + exts[best];
  })();
  const D = (() => {
    const n = args[3][0];
    const res = [];
    for (let k = 2; k < n; k++) {
      let p = true;
      for (let d = 2; d * d <= k; d++) if (k % d === 0) { p = false; break; }
      if (p) res.push(k);
    }
    return res;
  })();
  const E = (() => {
    const s = String(args[4][0]);
    let p = 1, found = false;
    for (const ch of s) {
      const d = ch.charCodeAt(0) - 48;
      if (d % 2 === 1) { p *= d; found = true; }
    }
    return found ? p : 0;
  })();
  return [A, B, C, D, E];
}

