function solve(args) {
  const absSign = (a) => {
    if (!a.length) return null;
    let sum = 0, neg = 0, zero = false;
    for (const x of a) {
      if (x === 0) zero = true;
      if (x < 0) neg++;
      sum += Math.abs(x);
    }
    if (zero) return 0;
    return neg % 2 ? -sum : sum;
  };
  const primes = (n) => {
    const r = [];
    for (let k = 2; k < n; k++) {
      let p = true;
      for (let d = 2; d * d <= k; d++) if (k % d === 0) { p = false; break; }
      if (p) r.push(k);
    }
    return r;
  };
  const oddProd = (n) => {
    let p = 1, found = false;
    for (const c of String(n)) {
      const d = +c;
      if (d % 2 === 1) { p *= d; found = true; }
    }
    return found ? p : 0;
  };
  const sortThirds = (a) => {
    const idx = [];
    for (let i = 0; i < a.length; i += 3) idx.push(i);
    const vals = idx.map(i => a[i]).sort((x, y) => x - y);
    const r = a.slice();
    idx.forEach((i, j) => { r[i] = vals[j]; });
    return r;
  };
  const ext = (name, arr) => {
    let best = 0, bestScore = -Infinity;
    for (let i = 0; i < arr.length; i++) {
      let s = 0;
      for (const c of arr[i]) {
        if (c >= 'A' && c <= 'Z') s++;
        else if (c >= 'a' && c <= 'z') s--;
      }
      if (s > bestScore) { bestScore = s; best = i; }
    }
    return name + '.' + arr[best];
  };
  return [
    absSign(args[0][0]),
    primes(args[1][0]),
