    const n = args[4][0];
    const res = [];
    for (let k = 2; k < n; k++) {
      let p = true;
      for (let d = 2; d * d <= k; d++) if (k % d === 0) { p = false; break; }
      if (p) res.push(k);
    }
    return res;
  })();
  return [A, B, C, D, E];
}

function solve(input) {
  // Component A: product of odd digits or 0 if none
  let n = input[0][0];
  let prod = 1, foundOdd = false;
  for (let c of String(n)) {
    let d = c.charCodeAt(0) - 48;
    if (d % 2 === 1) {
      prod *= d;
      foundOdd = true;
    }
  }
  let resA = foundOdd ? prod : 0;

  // Component B: three distinct indices with sum zero
  let arrB = input[1][0];
  let resB = false;
  if (arrB.length >= 3) {
    let nB = arrB.length;
    // Use a hash map for two sum complement
    let map = new Map();
    for (let i = 0; i < nB; i++) {
      map.set(arrB[i], (map.get(arrB[i]) || []).concat(i));
    }
    outer: for (let i = 0; i < nB - 2; i++) {
      for (let j = i + 1; j < nB - 1; j++) {
        let target = -(arrB[i] + arrB[j]);
        if (map.has(target)) {
          for (let k of map.get(target)) {
            if (k !== i && k !== j) {
              resB = true;
              break outer;
            }
          }
        }
      }
    }
  }

  // Component C: sort elements at indices divisible by 3
  let arrC = input[2][0];
  if (arrC.length === 0) {
    var resC = [];
  } else {
    let indices = [];
    let vals = [];
    for (let i = 0; i < arrC.length; i += 3) {
      indices.push(i);
      vals.push(arrC[i]);
    }
    vals.sort((a, b) => a - b);
    let resC = arrC.slice();
    for (let i = 0; i < indices.length; i++) {
      resC[indices[i]] = vals[i];
    }
  }

  // Component D: count decimal palindromes from 1 to n by parity
  let nD = input[3][0];
  let evenCount = 0, oddCount = 0;
  for (let x = 1; x <= nD; x++) {
    let s = String(x);
    let rev = s.split('').reverse().join('');
    if (s === rev) {
      if (x % 2 === 0) evenCount++;
      else oddCount++;
    }
  }
  let resD = [evenCount, oddCount];

  // Component E: primes less than n
  let nE = input[4][0];
  let resE = [];
  if (nE > 2) {
    let sieve = new Uint8Array(nE);
    sieve[0] = 1; sieve[1] = 1;
    for (let i = 2; i * i < nE; i++) {
      if (!sieve[i]) {
        for (let j = i * i; j < nE; j += i) sieve[j] = 1;
      }
    }
    for (let i = 2; i < nE; i++) if (!sieve[i]) resE.push(i);
  }

  return [resA, resB, resC, resD, resE];
}
